import{_ as i,c as e,o as t,aj as l}from"./chunks/framework.DNhrqZu5.js";const g=JSON.parse('{"title":"Vite 插件集成","description":"","frontmatter":{},"headers":[],"relativePath":"guide/vue3/vite.md","filePath":"guide/vue3/vite.md","lastUpdated":1777342606000}'),a={name:"guide/vue3/vite.md"},n=l('<h1 id="vite-插件集成" tabindex="-1">Vite 插件集成 <a class="header-anchor" href="#vite-插件集成" aria-label="Permalink to &quot;Vite 插件集成&quot;">​</a></h1><p>基于原生 ES 模块提供了丰富的内建功能，如速度快到惊人的模块热更新（HMR），使用 Rollup 打包你的代码，并且它是预配置的，可输出用于生产环境的高度优化过的静态资源。更多关于 <a href="https://cn.vitejs.dev/guide/" target="_blank" rel="noreferrer">Vite</a></p><p>模版集成了如下的 vite 插件（配置目录：<code>build/vite/plugins/</code>）</p><ul><li>unplugin-auto-import（按需加载，自动引入）</li><li>unplugin-vue-components（按需加载，自动引入组件）</li><li>vite-plugin-compression（开启 .gz 压缩）</li><li>@zhaojjiang/vite-plugin-eruda（控制台，方便移动端调试）</li><li>vite-plugin-imagemin（图片压缩）</li><li>vite-plugin-mock（引入 mockjs，本地模拟接口）</li><li>vite-plugin-pages（动态生成路由）</li><li>vite-plugin-progress（构建显示进度条）</li><li>vite-plugin-restart（监听配置文件修改自动重启 Vite）</li><li>vite-plugin-svg-icons（加载 SVG 文件，自动引入）</li><li>vite-plugin-pwa（PWA 支持）</li><li>vite-plugin-qrcode（开发时生成二维码，方便移动端调试）</li><li>@vitejs/plugin-basic-ssl（本地 HTTPS 开发支持）</li><li>rollup-plugin-visualizer（打包分析报告）</li></ul>',4),o=[n];function s(r,p,u,c,v,d){return t(),e("div",null,o)}const m=i(a,[["render",s]]);export{g as __pageData,m as default};
